"use strict";(globalThis.webpackChunkmy_website||=[]).push([[26686],{82171(e){e.exports=JSON.parse('{"slug":"eclipse-attack","title":"Eclipse Attack","short":"A network attack where a node is isolated from honest peers and connected only to attacker-controlled nodes.","category":"network","aliases":[],"mentalModel":null,"related":["proof-of-stake-attacks","ouroboros"],"sources":[],"link":null,"level":"advanced","body":"A network attack where a node is isolated from honest peers and connected only to attacker-controlled nodes. This prevents the node from seeing the legitimate chain. The node still fully validates everything it receives, but the attacker can feed it a stale or attacker-controlled view of the chain, enabling double-spends or transaction censorship against the victim."}')}}]);